import{_ as a,C as o,o as r,c as l,j as p,a as h,E as n,a6 as i}from"./chunks/framework.CnPv4DE1.js";const _=JSON.parse('{"title":"深思创作之死(以及如何领先所有人)","description":"","frontmatter":{"title":"深思创作之死(以及如何领先所有人)","originalTitle":"The Death Of Thoughtful Creation (& How To Get Ahead Of Everyone Else)","date":"2025-06-19","originalUrl":"https://thedankoe.com/letters/the-death-of-thoughtful-creation-how-to-get-ahead-of-everyone-else/","minutes":14,"sourceHash":"4b5060b433085b3b5fb2376b747c80322863e084fa452cabe088344ee3949b71","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/the-death-of-thoughtful-creation-how-to-get-ahead-of-everyone-else/"}]]},"headers":[],"relativePath":"letters/the-death-of-thoughtful-creation-how-to-get-ahead-of-everyone-else.md","filePath":"letters/the-death-of-thoughtful-creation-how-to-get-ahead-of-everyone-else.md"}'),s={name:"letters/the-death-of-thoughtful-creation-how-to-get-ahead-of-everyone-else.md"};function d(c,e,f,m,u,b){const t=o("ArticleMeta");return r(),l("div",null,[e[0]||(e[0]=p("h1",{id:"深思创作之死-以及如何领先所有人",tabindex:"-1"},[h("深思创作之死(以及如何领先所有人) "),p("a",{class:"header-anchor",href:"#深思创作之死-以及如何领先所有人","aria-label":'Permalink to "深思创作之死(以及如何领先所有人)"'},"​")],-1)),n(t),e[1]||(e[1]=i('<blockquote><p>人生中领先他人最简单的方法,就是投入一段时间进行技能开发。6到12个月。每天纯粹专注2到4小时。学习和构建。不只是刷教程视频,而是创造出真正能让你自己、他人或企业受益的优质项目。大多数人不会这么做,但那些做了的人,会领先所有人一大步。</p></blockquote><p>但大多数人的做法都错了。</p><p>他们仍然在为旧的工作范式学习技能、构建项目。</p><p>他们启动10个创业项目。他们源源不断地产出内容。他们堆叠设计、营销、编程、文案写作等技能,因为他们认为这样能提升自己的价值,从而赚更多钱。</p><p>他们执着于产出的数量,却牺牲了那些<em>值得推出</em>的东西。</p><p>他们做了很多质量平庸的事,而不是一件品质无可否认的事。</p><p>我们正经历着深思创作之死。这个世界正被更多的工厂填满,而不是园丁。为什么?</p><p>因为创作从未如此触手可及。</p><ul><li>你可以在AI里输入一句话,就能生成一个手机应用。</li><li>你可以在一天内生成一个月的内容量,并把它们排期发布到所有社交平台。</li><li>你可以把一张图片拖进ChatGPT,把它转化成提示词,然后用自己的风格重新创作出来。</li></ul><p>工作的未来是速度与艺术之间的一场战争。当任何人都能一键创造任何东西时,它也会在一键之间失去全部价值,而我们不再重视自己,因为我们深深意识到,自己把灵魂卖给了那台本该帮我们逃离机械生活的机器。</p><p>在速度至关重要的领域,你无法与机器竞争。</p><p>这为人类留下了意义、玩乐和信号的领域。</p><p>如果你想领先所有人,答案不在于源源不断地产出海量内容,寄望靠数字游戏取胜。相反,答案在于“更少”。</p><p>消费更少。产出更少。做得更少。</p><p>这听起来违反直觉,但这并不是什么新鲜事。</p><p>这正是世界上最成功的创意人、战略家和远见者们,创造出那些贯穿历史、经久不衰的书籍、产品以及科学与文化突破的方式。</p><h2 id="机器人工作-人类玩乐" tabindex="-1">机器人工作,人类玩乐 <a class="header-anchor" href="#机器人工作-人类玩乐" aria-label="Permalink to &quot;机器人工作,人类玩乐&quot;">​</a></h2><blockquote><p>未来的精妙之处,不在于人类对抗机器,而在于两者的分工:硅打磨掉必需品的粗糙边缘,让碳能够升华至意义。我们将淘汰咖啡师,神化厨师;让客服静默,让演员再次登场。驱动这两个领域的,是同一种自私的本能——消除摩擦,保留叙事——推动着一个世界的形成:最枯燥的杂务由电路完成,最鲜活的故事由会流血的人来讲述。</p><p>——克里斯·帕伊克(Chris Paik)</p></blockquote><p>要理解人类将在何处蓬勃发展,我们必须先看清人类不会在哪里蓬勃发展。</p><p>当任务关乎速度、准确性或实用性时,人类会成为巨大的累赘。这些正是推动自动化的驱动力。</p><p>我们无法忍受那个记下你点单却还是记错的服务员。无法忍受在车管所排长队,却被一个心情不好而拒绝你请求的工作人员打发走。无法忍受在你赶会议迟到时还试图跟你闲聊的Uber司机。</p><p>但当我们的心智脱离“为了完美结果必须做某事”的状态——当我们投入休闲之中——我们渴望的东西完全不同。</p><p>我们渴望有趣的东西。</p><p>我们渴望失败的可能性。</p><p>我们渴望的,正是我们心智运转所依赖的东西:</p><p>故事。戏剧性。新奇。神话与意义。我们甚至愿意为此付出真金白银。</p><p>与其去星巴克买一杯速冲的咖啡——那味道往往像是豆子在地狱之火中烘烤出来的——我们宁愿绕路去那家温馨的本地咖啡馆,那里的老板叫得出你的名字。</p><p>虽然我们更愿意让外卖直接送到家门口,不必见到送餐的人,但我们却愿意跨越半个地球,去某个我们一直梦想造访的地方,只为吃到想象中最美味的食物。</p><p>工作时,我们想要的是要点式摘要。婚礼上,我们想要的是手写的誓词。AI能投出完美的一球,但我们依然会把体育场坐满,眼睛离不开第九局最后那个击球手。</p><p>但这并不能消除工作的必要性。如果我们想掌控自己的休闲时间,仍然需要有工作被完成。那么解决方案就是:利用机器减少我们感知到的“工作”,增加我们花在休闲上的时间,以创造出值得与世界分享的有意义的故事。</p><p>换句话说,你通过风险和故事让自己变得不可替代,然后把这一点融入你创造的一切之中。你把失败当作燃料,借此变得不可替代。</p><p>这是历史上一个隐藏的事实。科技的进步为休闲腾出了空间,让人们能够发现并追求新的兴趣。不幸的是,父母和承袭上一代价值观的学校教育,让我们相信“多工作”是高尚的,却没意识到他们正在把我们推向平庸的人生。</p><p>在早期的农业社会,马拉犁的发明带来了粮食盈余,人们从而有了空闲时间去发明数学和文字。这是历史上第一次,大量人口能够从事这类活动,包括深度沉思,由此催生了轴心时代,诞生了乔达摩·佛陀(Gautama Buddha)、老子(Lao Tzu)、苏格拉底(Socrates)等人的哲学思想。</p><p>到了工业时代,尽管许多人仍在从事艰苦而毫无意义的工作,但我们已经拥有体育、电影、内容创作、手工艺作坊,以及可以“作为工作”存在的深度体验。以玩乐为核心的工作——或者说使命——并不是什么新鲜事。那些本可以被自动化取代的手工作品,人们购买它们并不是为了速度和便利。当然,许多人在这些工作中把自己燃烧殆尽,因为他们在生存状态中活得太久,以至于那已成为他们的身份认同,但也有很多人并不把这些当作工作,而更多地把它们视为一种生活方式。</p><p>一种<em>休闲经济</em>正在我们眼前悄然浮现。</p><p>再进一步,如果我们审视史蒂夫·乔布斯(Steve Jobs)、查尔斯·达尔文(Charles Darwin),以及各种以自己的创造改变世界的思想家,我们会发现,他们创造力的顶峰源于休息、散步和休闲。在我看来,休闲就是发现和探索的过程,是追求自己兴趣的行为。</p><p>随着机器人消灭工作,人类便升华至玩乐之境。</p><h2 id="最伟大的技能不是创作-而是策展" tabindex="-1">最伟大的技能不是创作,而是策展 <a class="header-anchor" href="#最伟大的技能不是创作-而是策展" aria-label="Permalink to &quot;最伟大的技能不是创作,而是策展&quot;">​</a></h2><blockquote><p>你我并不像牛。我们不是天生要整天吃草的动物。我们生来就该像狮子一样去狩猎。就我们全能型的进化而言,我们更接近肉食动物,而不是草食动物。作为一名智力上的运动员,你要像运动员那样运作。也就是说,你先刻苦训练,然后冲刺,然后休息,然后重新评估。这种“每天用同样的时间坐在那里死磕,就能获得线性产出”的想法……那是机器的运作方式。机器才该朝九晚五地工作,人类不该如此。</p><p>——纳瓦尔(Naval)</p></blockquote><p>我们选择的工作定义了我们是谁。</p><p>如果我们选择投身于一个以效率和优化为目标的系统,我们自己也会变成那个目标。我们会变成机器里的一个齿轮。这为超专业化描绘出一幅残酷的图景。当你把心智局限在一个维度里,你就成了它的奴隶。</p><p>在工业化之前,奴隶被要求终其一生只执行一小部分固定任务。而另一方面,大约80%的美国自由劳动者是自雇的农民或工匠。他们被期望去追求自己的兴趣,一生中做许多不同的事,因为他们被期望自主安排自己的劳动。如今,美国只有大约10%的人是自雇者。</p><p>工业革命(想想学校教育和大规模雇佣制度)改变了我们与工作的关系。缓慢地,然后突然地,数百万人被卷入了由他人指挥、任务预先设定好的工作之中。</p><p>就这样,作为一种价值观的自我管理消失了,我们心甘情愿地把自己安排好,等着被机器取代。</p><p>不管我怎么反复思考——过去五年我一直在写这个主题——对大多数人,尤其是那些渴望创造力和自主权的人来说,最主要的解法是成为一名现代工匠。确切地说,是数字工匠。一位信息时代的博学之士。</p><p>这是一次彻底的转变:从为别人生产,转向为自己生产。</p><p>这话说到现在已经有点老生常谈了,但仍值得提一提以作提醒:你从未像现在这样,拥有维系工匠级别的工作——却让它感觉像玩乐——所需的工具、资源和人脉。你不需要成为下一个亿万富翁,你只需要生存下来(还能留点喘息的空间)。</p><p>你可以获取任何信息。</p><p>你可以在不用花费数年习得技能的情况下,构建任何东西。</p><p>你可以吸引到一群支持者的关注,单凭做自己就能获得报酬。</p><p>AI能在一键之间源源不断地产出无限内容,而这恰恰就是问题所在。</p><p>记住,在速度和实用性上,你无法与机器竞争。当有人想要不带偏见的新闻和纯粹的“怎么做”建议时,他们会去<em>搜索</em>它,并对任何形式的摩擦感到厌烦。AI生成的内容在我们需要快速获取信息时,可以非常有用。</p><p>但当我们并不是在搜索什么具体的东西时——而这是<em>大多数时候</em>的情况——我们渴望的是不同的东西。</p><p>我们读一本虚构小说。我们看一段讲有趣观点的视频。我们听一档由两位自己最喜欢的人物主持的播客。我们听新音乐。我们渴望一个故事、一个观点、一个在噪音中点燃我们大脑的信号。</p><p>在智慧、洞见、深度与意义的领域——机器人无从插足。</p><p><em>我们所在意的,是别人用心投入过的东西。</em></p><p>如果那家本地咖啡馆真的会因为成本和速度而被淘汰出局,它早就该关门了,但它们却门庭若市,尽管一杯咖啡卖到7美元。</p><p>爱马仕(Hermes)一个包的制作成本只要300美元,却能卖到8万美元,这一点根本不重要。重要的是品牌。是故事。是<em>谁</em>做的。是工艺与细节。这才是人们愿意付出高溢价的原因。至于中国能用几块钱做出同样的奢侈品,这一点只对错误的受众才有意义。</p><p>但人们心甘情愿把辛苦赚来的钱花在手工制品上,还有另一个原因——一个可以被复制的原因:</p><p><em>品味。</em></p><p>当任何人都能创造任何东西时,判断力和克制力就变得至关重要。<em>策展开始比创作更重要。</em>死记硬背学术知识、成为一座信息图书馆,已经不再是一种身份象征。真正重要的,是你<em>选择</em>让哪些有限的观念占据你的心智。</p><p>问题已经不再是你<em>能不能</em>创造出它。</p><p>而是你<em>应不应该</em>。</p><h2 id="如何培养并运用品味" tabindex="-1">如何培养并运用品味 <a class="header-anchor" href="#如何培养并运用品味" aria-label="Permalink to &quot;如何培养并运用品味&quot;">​</a></h2><p>要培养品味,你需要构建属于自己的东西,因为品味是无法外包的。</p><p>品味是一种通过练习和对手艺的专注投入才能获得的技能。</p><p>仅这一点就能解释为什么大多数人正在落后。他们痴迷于数量而不是质量。他们为了赚钱而创作，而不是为了创作而赚钱。他们学习任何承诺快速赚钱的技能，而我们都知道那最终会怎样。</p><p>你需要一个<em>目的</em>，作为过滤我们每天被过度暴露的信息水龙头的滤网。你必须对谁和什么能接触到你的思维毫不留情。你需要认清这样一个事实：短信、社交媒体信息流，以及对孕育创造力所需的那种寂静的空前侵占，并不是我们大脑天生适应的东西。</p><p>有品味的人拥有一种能拒绝感觉不对的信息的思维。他们看一个设计、一个产品或一篇帖子时，能感觉到有什么东西缺失了，或者有什么东西应该被彻底舍弃，或者这东西本就不该存在。</p><p>我们这个时代最伟大的头脑，并不是在消费更多。因为高质量的输出源自高质量的输入。你把注意力给了什么，就塑造了你如何思考，而当你不去选择自己在建造什么、为谁而建造时，你就成了奴隶。不是肉体上的，而是精神上的。你的创造力，会被除你自己之外的任何人所指挥的工作，同时扼杀和耗尽。</p><p>当机器能够同时思考一切时，我们的任务就是拥有标准。</p><p>去过滤我们允许进入大脑的信息。</p><p>去筛选值得被打造成形的想法。</p><p>去选择那种我们无法把自己从中拽走的工作。</p><p>但要怎么做？这些听起来都很好、很有见地，但我们究竟该如何实际去做？</p><p>我们该如何以品味为北极星，来引导自己的职业生涯？</p><h3 id="把冒险、迭代和精工放在首位" tabindex="-1">把冒险、迭代和精工放在首位 <a class="header-anchor" href="#把冒险、迭代和精工放在首位" aria-label="Permalink to &quot;把冒险、迭代和精工放在首位&quot;">​</a></h3><p>不要专注于你擅长什么。</p><p>要专注于你独有的做事方式，而这只能通过实践去发现，而非空想。</p><p>你会在创造一个值得与他人分享的故事的过程中，发现自己的独特之处所在。你个人的故事，源自你个人的意识——那是任何人，甚至AI，都无法完全触及的东西——是这个星球上最独特的东西。如果你倾向于依赖任何其他东西，而不是那一串有趣的、为你所创造的一切带来既有共鸣又新颖视角的失败与成功经历，你未来将很难与人竞争。</p><p>创造一个值得讲述的故事的唯一方法，就是把冒险放在首位。就是在你所选择的方向上做出深思熟虑的决定。就是避免去顺从任何人、任何事、任何信念或任何世界观，而是通过对这些事物的拒绝和质疑，去开辟自己的道路。</p><p>除此之外，品味是通过迭代诞生的。</p><p>这是一个永无止境的过程。我曾以为自己写的第一份通讯还不错，但当我现在回头看，那是我这辈子见过最令人反胃的东西。我现在觉得我的通讯写得相当不错，尽管比以前好了很多，但一年后我再回头看时</p><p>设计师、电影制作人或程序员，都可以回顾自己过去作品的各个版本，注意到自己品味发展过程中那种实实在在的差异。</p><p>正因如此，那些从不开始，或者两周就放弃的人，永远都无法成功。你可能以为自己有品味……我是说，看着世界上某个东西，认同它是有品味地做出来的很容易，但当你坐下来试图复刻它时，你会发现你和他们之间的差距是巨大的。</p><p>无论你研究了多少，当你开始动手时，品味都是从零开始增长的。</p><h3 id="带着用心去创造-直到你真正在乎" tabindex="-1">带着用心去创造，直到你真正在乎 <a class="header-anchor" href="#带着用心去创造-直到你真正在乎" aria-label="Permalink to &quot;带着用心去创造，直到你真正在乎&quot;">​</a></h3><p>追随你的热情，是个糟糕的建议。</p><p>不是因为它错了，而是因为它具有误导性。</p><p>你不是去追随你的热情。你是通过长期以热情去做某件事，直到发现这门手艺的深度，从而培养出对它的强烈热情。你是在追求一个目标的过程中<em>生成</em>热情——这个目标你或许本不想追求，但你把它视为通往你想要的生活所必需的东西，于是你关掉大脑，硬是把它做了下去。</p><p>变得不可替代的第一步，是每天至少留出一个小时用于纯粹的手艺打磨。换句话说，就是打造一个项目。一份<em>创造</em>。某种你和他人都能使用并从中受益的东西。这是从消费者到生产者的关键转变，这个转变必须发生。</p><p>这个项目具体是什么并不重要，因为你现在学的任何职业或特定工作技能，未来都不会重要。你打造一个项目，是为了发展能动性和品味，而不是为了在市场上凭速度和准确性表现所带来的金钱回报。</p><p>一个有意义的项目会塑造你是谁、你如何思考。它实实在在地重塑你的思维。它教你如何学习。它悄然构建未来所必需的软技能，比如感知力、适应力和韧性。它迫使你专注于在各种技能之间获取通用技巧，而不是某个特定职业的技能——这些通用技巧会转移到你所创造的任何其他东西上。</p><h3 id="获取关注-建立信任" tabindex="-1">获取关注，建立信任 <a class="header-anchor" href="#获取关注-建立信任" aria-label="Permalink to &quot;获取关注，建立信任&quot;">​</a></h3><p>你可以开一家本地生意。</p><p>你可以创造实体产品或商品。</p><p>但对于正在读这篇文章的你，我有信心95%甚至更多的人都具备创造性的优势。你明白互联网上可以建立的杠杆。你看到了数字世界如何让你能够主导自己的职业生涯。因此，你打造的项目应该反映这一点。</p><p>你不需要资本就能在线上开店。你不需要身处正确的物理地点才能与合适的人建立联系。你不需要唱片公司、出版商或雇主来<em>给予</em>你工作。但你确实需要关注和信任。</p><p>记住，任何人都可以创造任何东西。这是我们曾能自信说出的最令人解放的话之一。</p><p>既然如此，你要如何脱颖而出？</p><p>通过整合我们目前所谈到的一切。</p><p>首先，建立一个个人品牌，或者一个有个性的品牌，并公开发布你的作品。你的故事必须处于最前沿、最核心的位置。</p><p>其次，为了有品味的输出去筛选你的输入。在这个充满令人难以忍受的噪音的世界里，成为一座信号的灯塔。追求你的兴趣，分享你所在乎的想法。用不了多久，只要有恰当的迭代量，其他人也会开始在乎。</p><p>第三，打造一个有意义的项目，并将其转化为一个产品。音乐。写作。设计。软件。任何东西都行。因为残酷的现实是：如果你不卖自己的产品，你就会被迫去替别人卖产品。你的劳动，从而你的思维，将被别人所支配。要卖出一个产品，你需要关注，但你不需要为此出卖自己的灵魂。</p><p>给自己6到12个月的时间。</p><p>每天2到4小时的纯粹专注。</p><p>我无法给你那条路，因为你无法复制我的故事。</p><p>我有信心，我已经给了对的人足够多的东西，让他们能够自己去把它琢磨出来。</p><p>祝你好运。</p><p>——Dan</p><p>这里有几篇相关的付费和免费文章，供你继续阅读：</p><ul><li><a href="https://letters.thedankoe.com/p/full-course-the-one-person-business?lli=1" target="_blank" rel="noreferrer">完整课程：一人企业发射台</a></li><li><a href="https://letters.thedankoe.com/p/how-to-build-a-better-personal-brand?lli=1" target="_blank" rel="noreferrer">如何打造比99%的人更好的个人品牌</a></li><li><a href="https://letters.thedankoe.com/p/how-to-build-a-world-the-2-hour-content?lli=1" target="_blank" rel="noreferrer">如何打造一个世界：2小时内容生态系统</a></li><li><a href="https://letters.thedankoe.com/p/the-future-proof-manifesto?lli=1" target="_blank" rel="noreferrer">未来防御宣言</a></li></ul><hr><p><a href="/en/letters/the-death-of-thoughtful-creation-how-to-get-ahead-of-everyone-else">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',114))])}const g=a(s,[["render",d]]);export{_ as __pageData,g as default};
